    @classmethod
    def InitFromBuf(cls, buf, pos):
        tmpMplPhasingSolution = mplPhasingSolution()
        tmpMplPhasingSolution.Init(buf, pos)
        return cls.InitFromObj(tmpMplPhasingSolution)

    @classmethod
    def InitFromPackedBuf(cls, buf, pos=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, pos)
        return cls.InitFromBuf(buf, pos+n)

    @classmethod
    def InitFromObj(cls, tmpMplPhasingSolution):
        x = mplPhasingSolutionT()
        x._UnPack(tmpMplPhasingSolution)
        return x

    # mplPhasingSolutionT
    def _UnPack(self, mplPhasingSolution):
        if mplPhasingSolution is None:
            return
        self.PHASE_ANGLE_DEG = mplPhasingSolution.PHASE_ANGLE_DEG()
        self.ACHIEVED_PHASE_ANGLE_DEG = mplPhasingSolution.ACHIEVED_PHASE_ANGLE_DEG()
        self.REQUESTED_SEMI_MAJOR_AXIS_KM = mplPhasingSolution.REQUESTED_SEMI_MAJOR_AXIS_KM()
        self.REQUESTED_PERIOD_S = mplPhasingSolution.REQUESTED_PERIOD_S()
        self.FLOOR_RADIUS_KM = mplPhasingSolution.FLOOR_RADIUS_KM()
        self.CLAMPED_TO_FLOOR = mplPhasingSolution.CLAMPED_TO_FLOOR()
        self.FAR_APSE_RADIUS_KM = mplPhasingSolution.FAR_APSE_RADIUS_KM()
        self.PHASING_RADIUS_KM = mplPhasingSolution.PHASING_RADIUS_KM()
        self.RELATIVE_PHASE_ANGLE_DEG = mplPhasingSolution.RELATIVE_PHASE_ANGLE_DEG()
        self.CATCH_UP_ANGLE_DEG = mplPhasingSolution.CATCH_UP_ANGLE_DEG()
        self.FALL_BEHIND_ANGLE_DEG = mplPhasingSolution.FALL_BEHIND_ANGLE_DEG()
        self.DIRECTION = mplPhasingSolution.DIRECTION()
        if mplPhasingSolution.CHASER() is not None:
            self.CHASER = mplElements.mplElementsT.InitFromObj(mplPhasingSolution.CHASER())
        if mplPhasingSolution.TARGET() is not None:
            self.TARGET = mplElements.mplElementsT.InitFromObj(mplPhasingSolution.TARGET())
        self.RAAN_DIFFERENCE_DEG = mplPhasingSolution.RAAN_DIFFERENCE_DEG()
        self.INCLINATION_DIFFERENCE_DEG = mplPhasingSolution.INCLINATION_DIFFERENCE_DEG()
        self.PLANE_ANGLE_DEG = mplPhasingSolution.PLANE_ANGLE_DEG()
        self.SEMI_MAJOR_AXIS_DIFFERENCE_KM = mplPhasingSolution.SEMI_MAJOR_AXIS_DIFFERENCE_KM()
        self.COPLANAR = mplPhasingSolution.COPLANAR()
        self.COPLANAR_TOLERANCE_DEG = mplPhasingSolution.COPLANAR_TOLERANCE_DEG()
        self.NEAR_CIRCULAR = mplPhasingSolution.NEAR_CIRCULAR()
        self.ECCENTRICITY_TOLERANCE = mplPhasingSolution.ECCENTRICITY_TOLERANCE()
        self.CO_ORBITAL = mplPhasingSolution.CO_ORBITAL()
        self.CO_ORBITAL_TOLERANCE_KM = mplPhasingSolution.CO_ORBITAL_TOLERANCE_KM()
        self.CO_ORBITAL_TOLERANCE_FRACTION = mplPhasingSolution.CO_ORBITAL_TOLERANCE_FRACTION()
        self.RECOMMENDED_REVOLUTIONS = mplPhasingSolution.RECOMMENDED_REVOLUTIONS()
        self.REVOLUTIONS_FROM_CALLER = mplPhasingSolution.REVOLUTIONS_FROM_CALLER()
        self.MAX_REVOLUTIONS = mplPhasingSolution.MAX_REVOLUTIONS()
        self.DELTA_V_BUDGET_KM_S = mplPhasingSolution.DELTA_V_BUDGET_KM_S()
        self.WITHIN_BUDGET = mplPhasingSolution.WITHIN_BUDGET()

    # mplPhasingSolutionT
    def Pack(self, builder):
        if self.CHASER is not None:
            CHASER = self.CHASER.Pack(builder)
        if self.TARGET is not None:
            TARGET = self.TARGET.Pack(builder)
        mplPhasingSolutionStart(builder)
        mplPhasingSolutionAddPHASE_ANGLE_DEG(builder, self.PHASE_ANGLE_DEG)
        mplPhasingSolutionAddACHIEVED_PHASE_ANGLE_DEG(builder, self.ACHIEVED_PHASE_ANGLE_DEG)
        mplPhasingSolutionAddREQUESTED_SEMI_MAJOR_AXIS_KM(builder, self.REQUESTED_SEMI_MAJOR_AXIS_KM)
        mplPhasingSolutionAddREQUESTED_PERIOD_S(builder, self.REQUESTED_PERIOD_S)
        mplPhasingSolutionAddFLOOR_RADIUS_KM(builder, self.FLOOR_RADIUS_KM)
        mplPhasingSolutionAddCLAMPED_TO_FLOOR(builder, self.CLAMPED_TO_FLOOR)
        mplPhasingSolutionAddFAR_APSE_RADIUS_KM(builder, self.FAR_APSE_RADIUS_KM)
        mplPhasingSolutionAddPHASING_RADIUS_KM(builder, self.PHASING_RADIUS_KM)
        mplPhasingSolutionAddRELATIVE_PHASE_ANGLE_DEG(builder, self.RELATIVE_PHASE_ANGLE_DEG)
        mplPhasingSolutionAddCATCH_UP_ANGLE_DEG(builder, self.CATCH_UP_ANGLE_DEG)
        mplPhasingSolutionAddFALL_BEHIND_ANGLE_DEG(builder, self.FALL_BEHIND_ANGLE_DEG)
        mplPhasingSolutionAddDIRECTION(builder, self.DIRECTION)
        if self.CHASER is not None:
            mplPhasingSolutionAddCHASER(builder, CHASER)
        if self.TARGET is not None:
            mplPhasingSolutionAddTARGET(builder, TARGET)
        mplPhasingSolutionAddRAAN_DIFFERENCE_DEG(builder, self.RAAN_DIFFERENCE_DEG)
        mplPhasingSolutionAddINCLINATION_DIFFERENCE_DEG(builder, self.INCLINATION_DIFFERENCE_DEG)
        mplPhasingSolutionAddPLANE_ANGLE_DEG(builder, self.PLANE_ANGLE_DEG)
        mplPhasingSolutionAddSEMI_MAJOR_AXIS_DIFFERENCE_KM(builder, self.SEMI_MAJOR_AXIS_DIFFERENCE_KM)
        mplPhasingSolutionAddCOPLANAR(builder, self.COPLANAR)
        mplPhasingSolutionAddCOPLANAR_TOLERANCE_DEG(builder, self.COPLANAR_TOLERANCE_DEG)
        mplPhasingSolutionAddNEAR_CIRCULAR(builder, self.NEAR_CIRCULAR)
        mplPhasingSolutionAddECCENTRICITY_TOLERANCE(builder, self.ECCENTRICITY_TOLERANCE)
        mplPhasingSolutionAddCO_ORBITAL(builder, self.CO_ORBITAL)
        mplPhasingSolutionAddCO_ORBITAL_TOLERANCE_KM(builder, self.CO_ORBITAL_TOLERANCE_KM)
        mplPhasingSolutionAddCO_ORBITAL_TOLERANCE_FRACTION(builder, self.CO_ORBITAL_TOLERANCE_FRACTION)
        mplPhasingSolutionAddRECOMMENDED_REVOLUTIONS(builder, self.RECOMMENDED_REVOLUTIONS)
        mplPhasingSolutionAddREVOLUTIONS_FROM_CALLER(builder, self.REVOLUTIONS_FROM_CALLER)
        mplPhasingSolutionAddMAX_REVOLUTIONS(builder, self.MAX_REVOLUTIONS)
        mplPhasingSolutionAddDELTA_V_BUDGET_KM_S(builder, self.DELTA_V_BUDGET_KM_S)
        mplPhasingSolutionAddWITHIN_BUDGET(builder, self.WITHIN_BUDGET)
        mplPhasingSolution = mplPhasingSolutionEnd(builder)
        return mplPhasingSolution
